//! Every shared-memory, handshake and envelope layout constant this client
//! uses, in one place. Each is held to the implementation-independent table
//! `src/tests/fixtures/bus/layout_vectors.tsv` (generated by
//! `scripts/gen_bus_layout_vectors.py`) by the test below, in both directions,
//! exactly as the C and Go clients are. The frame header's byte layout is held
//! to `wire_vectors.tsv` instead.
//!
//! A few offsets name fields only the host writes, or reserved space; the
//! client never touches them, but they are declared so the table is held in
//! full.

// ---- versions -------------------------------------------------------------
pub(crate) const SPEC_VERSION: u32 = 1;
pub(crate) const LAYOUT_VERSION: u32 = 1;

// ---- control region (bus_control_t; D1, D4, D12) ---------------------------
pub(crate) const CTL_MAGIC: u32 = 0x4c54_4342; // "BCTL"
pub(crate) const CTL_BYTES: usize = 96;
pub(crate) const CTL_OFF_MAGIC: usize = 0;
pub(crate) const CTL_OFF_SPEC: usize = 4;
pub(crate) const CTL_OFF_LAYOUT: usize = 8;
pub(crate) const CTL_OFF_FLAGS: usize = 12;
pub(crate) const CTL_OFF_SLOT: usize = 16;
pub(crate) const CTL_OFF_INLINE: usize = 20;
pub(crate) const CTL_OFF_QUEUE_CAP: usize = 24;
pub(crate) const CTL_OFF_LEASE_VIEW_SLOTS: usize = 28; // D12, formerly reserved0
pub(crate) const CTL_OFF_ARENA: usize = 32;
pub(crate) const CTL_OFF_EPOCH: usize = 40;
#[cfg_attr(
    not(test),
    expect(dead_code, reason = "host-owned or reserved; held to the table")
)]
pub(crate) const CTL_OFF_HEARTBEAT: usize = 48;
pub(crate) const CTL_OFF_LEASE_VIEW_OFF: usize = 56; // D12, formerly reserved1[0]
#[cfg_attr(
    not(test),
    expect(dead_code, reason = "host-owned or reserved; held to the table")
)]
pub(crate) const CTL_OFF_RESERVED1: usize = 64;
/// D12: the control region advertises a lease view after its header.
pub(crate) const CTL_F_LEASE_VIEW: u32 = 0x1;

// ---- lease view (D12) -------------------------------------------------------
pub(crate) const LEASE_VIEW_SLOTS: usize = 4096;
pub(crate) const LEASE_VIEW_ENTRY: usize = 16;
pub(crate) const LEASE_OFF_GENERATION: usize = 0;
pub(crate) const LEASE_OFF_LEN: usize = 4;
pub(crate) const LEASE_OFF_OFFSET: usize = 8;
/// The control region with its lease view.
pub(crate) const CTL_BYTES_WITH_VIEW: usize = CTL_BYTES + LEASE_VIEW_SLOTS * LEASE_VIEW_ENTRY;

// ---- queue-pair region (bus_qpair_hdr_t) -----------------------------------
pub(crate) const QP_MAGIC: u32 = 0x5250_4251; // bytes spell "QBPR"
pub(crate) const QP_BYTES: usize = 96;
pub(crate) const QP_OFF_MAGIC: usize = 0;
pub(crate) const QP_OFF_SLOT: usize = 4;
pub(crate) const QP_OFF_CAP: usize = 8;
#[cfg_attr(
    not(test),
    expect(dead_code, reason = "host-owned or reserved; held to the table")
)]
pub(crate) const QP_OFF_DATA_CREDITS: usize = 12;
#[cfg_attr(
    not(test),
    expect(dead_code, reason = "host-owned or reserved; held to the table")
)]
pub(crate) const QP_OFF_CONTROL_CREDITS: usize = 16;
pub(crate) const QP_OFF_CONTROL_LOST: usize = 20;
pub(crate) const QP_OFF_INBOUND: usize = 24;
pub(crate) const QP_OFF_OUTBOUND: usize = 28;
pub(crate) const QP_OFF_HEARTBEAT: usize = 32;
#[cfg_attr(
    not(test),
    expect(dead_code, reason = "host-owned or reserved; held to the table")
)]
pub(crate) const QP_OFF_RESERVED: usize = 40;
/// Each ring starts on a 64-byte boundary after the header.
pub(crate) const QP_RING_ALIGN: usize = 64;

// ---- ring (bus_ring_shared_t) -----------------------------------------------
pub(crate) const RING_MAGIC: u32 = 0x474e_4952; // "RING"
pub(crate) const RING_OFF_MAGIC: usize = 0;
pub(crate) const RING_OFF_SLOT: usize = 4;
pub(crate) const RING_OFF_CAP: usize = 8;
pub(crate) const RING_OFF_MASK: usize = 12;
pub(crate) const RING_OFF_SLOTS: usize = 16;
pub(crate) const RING_OFF_HEAD: usize = 64;
pub(crate) const RING_OFF_TAIL: usize = 128;
/// Ring header size; the slot array starts here.
pub(crate) const RING_HDR: usize = 192;

// ---- arena region (bus_arena_hdr_t) -----------------------------------------
pub(crate) const ARENA_MAGIC: u32 = 0x4e52_4142; // "BARN"
pub(crate) const ARENA_HDR: usize = 16;
pub(crate) const ARENA_OFF_MAGIC: usize = 0;
#[cfg_attr(
    not(test),
    expect(dead_code, reason = "host-owned or reserved; held to the table")
)]
pub(crate) const ARENA_OFF_RESERVED: usize = 4;
pub(crate) const ARENA_OFF_SIZE: usize = 8;

// ---- attach handshake --------------------------------------------------------
pub(crate) const ATTACH_REQ_MAGIC: u32 = 0x5152_4241; // "ABRQ"
pub(crate) const ATTACH_REQ_BYTES: usize = 16;
pub(crate) const ATTACH_REQ_OFF_MAGIC: usize = 0;
pub(crate) const ATTACH_REQ_OFF_WIRE_MIN: usize = 4;
pub(crate) const ATTACH_REQ_OFF_WIRE_MAX: usize = 6;
pub(crate) const ATTACH_REQ_OFF_CLASS: usize = 8;
pub(crate) const ATTACH_REQ_OFF_REF: usize = 12;
pub(crate) const ATTACH_REPLY_MAGIC: u32 = 0x5052_4241; // "ABRP"
pub(crate) const ATTACH_REPLY_BYTES: usize = 48;
pub(crate) const ATTACH_REPLY_OFF_MAGIC: usize = 0;
pub(crate) const ATTACH_REPLY_OFF_STATUS: usize = 4;
pub(crate) const ATTACH_REPLY_OFF_HANDLE: usize = 8;
pub(crate) const ATTACH_REPLY_OFF_WIRE: usize = 12;
pub(crate) const ATTACH_REPLY_OFF_SLOT: usize = 16;
pub(crate) const ATTACH_REPLY_OFF_INLINE: usize = 20;
pub(crate) const ATTACH_REPLY_OFF_QUEUE_CAP: usize = 24;
#[cfg_attr(
    not(test),
    expect(dead_code, reason = "host-owned or reserved; held to the table")
)]
pub(crate) const ATTACH_REPLY_OFF_RESERVED: usize = 28;
pub(crate) const ATTACH_REPLY_OFF_ARENA: usize = 32;
pub(crate) const ATTACH_REPLY_OFF_EPOCH: usize = 40;
pub(crate) const ATTACH_STATUS_OK: u32 = 0;
pub(crate) const ATTACH_STATUS_DENIED_POLICY: u32 = 1;
pub(crate) const ATTACH_STATUS_DENIED_VERSION: u32 = 2;
pub(crate) const ATTACH_STATUS_DENIED_NOSLOT: u32 = 3;
pub(crate) const ATTACH_STATUS_PROTOCOL: u32 = 4;
/// A successful attach carries exactly these descriptors, in this order.
pub(crate) const ATTACH_FDS: usize = 3;
pub(crate) const ATTACH_FD_CONTROL: usize = 0;
pub(crate) const ATTACH_FD_ARENA: usize = 1;
pub(crate) const ATTACH_FD_QPAIR: usize = 2;

// ---- lease-release payload (D12) ---------------------------------------------
pub(crate) const LEASE_RELEASE_OFF_LEASE: usize = 0;
pub(crate) const LEASE_RELEASE_OFF_GENERATION: usize = 4;

// ---- AMOD envelope -------------------------------------------------------------
pub(crate) const AMOD_OFF_MAGIC: usize = 0;
pub(crate) const AMOD_OFF_VERSION: usize = 4;
pub(crate) const AMOD_OFF_HEADER_LEN: usize = 6;
pub(crate) const AMOD_OFF_OPERATION: usize = 8;
pub(crate) const AMOD_OFF_STATUS: usize = 10;
pub(crate) const AMOD_OFF_STAGE: usize = 12;
pub(crate) const AMOD_OFF_FLAGS: usize = 16;
pub(crate) const AMOD_OFF_BODY_LEN: usize = 20;
pub(crate) const AMOD_OFF_DEADLINE: usize = 24;
pub(crate) const AMOD_OFF_TRACE: usize = 32;

