    #[test]
    fn layout_vectors() {
        let path = std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
            .join("../../src/tests/fixtures/bus/layout_vectors.tsv");
        let text = std::fs::read_to_string(&path).expect("read layout_vectors.tsv");
        let want = rust_layout();
        let mut seen = std::collections::HashSet::new();
        let mut errors = Vec::new();
        for line in text.lines() {
            if line.is_empty() || line.starts_with('#') {
                continue;
            }
            let (name, value) = line.split_once('\t').expect("name\\tvalue");
            let value = match value.strip_prefix("0x") {
                Some(h) => u64::from_str_radix(h, 16),
                None => value.parse(),
            }
            .unwrap_or_else(|_| panic!("{name}: bad value {value}"));
            match want.get(name) {
                None => errors.push(format!(
                    "row {name} has no Rust counterpart (add one to layout.rs)"
                )),
                Some(got) if *got != value => {
                    errors.push(format!("{name}: table {value}, Rust {got}"))
                }
                Some(_) => {}
            }
            if !seen.insert(name.to_string()) {
                errors.push(format!("duplicate row {name}"));
            }
        }
        for name in want.keys() {
            if !seen.contains(*name) {
                errors.push(format!("Rust value {name} is missing from the table"));
            }
        }
        assert!(errors.is_empty(), "layout drift:\n{}", errors.join("\n"));
        assert!(!seen.is_empty());
    }
